package pfm.android;

import android.app.*;
import android.content.*;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Qualification uses the same archived standings and frozen entrants as the recurring UCL. */
public final class NativeEuropeCenter {
 private NativeEuropeCenter(){}
 private static class Q{String code,club,id;int rank,points;Q(String c,String n,int r,int p){code=c;club=n;rank=r;points=p;}}
 private static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 private static TextView text(Context c,String s,float z,boolean b){TextView v=new TextView(c);v.setText(s);v.setTextSize(z);v.setPadding(dp(c,8),dp(c,6),dp(c,8),dp(c,6));if(b)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 private static String league(String code){for(int i=0;i<NativeWorldCenter.C.length;i++)if(code.equals(NativeWorldCenter.C[i]))return NativeWorldCenter.N[i];return code;}
 private static int cl(String code){return UclSeason.slots(code);}
 private static int el(String code){return EuropeanPlaces.europa(code);}
 private static ArrayList<Q> qualifiers(boolean champions){ArrayList<Q> out=new ArrayList<Q>();HashSet<String> frozen=new HashSet<String>();if(NativeTransferCalendar.played()>=NativeTransferCalendar.total())try{for(ArrayList<String> group:(champions?NativeMatchJournal.uclGroups(AndroidRuntime.context(),NativeWorldCenter.season()+1):NativeMatchJournal.europaGroups(AndroidRuntime.context(),NativeWorldCenter.season()+1)))frozen.addAll(group);}catch(Exception ignored){}for(String code:NativeWorldCenter.C){ArrayList<Q> table=new ArrayList<Q>();try{HashMap<String,String> names=new HashMap<String,String>();for(NativeCareerStore.Club club:NativeCareerStore.ensure(AndroidRuntime.context()).clubs)names.put(club.id,club.name);int rank=0;for(UclSeason.Standing row:NativeMatchJournal.qualifyingTable(AndroidRuntime.context(),code)){Q q=new Q(code,names.get(row.id),++rank,row.points);q.id=row.id;table.add(q);}}catch(Exception ignored){}int from=champions?1:cl(code)+1,to=champions?cl(code):cl(code)+el(code);for(Q q:table)if(!frozen.isEmpty()?frozen.contains(q.id):q.rank>=from&&q.rank<=to)out.add(q);}return out;}
 private static ArrayAdapter<Q> adapter(Activity a,ArrayList<Q> qs){return new ArrayAdapter<Q>(a,android.R.layout.simple_list_item_1,qs){public View getView(int n,View old,ViewGroup parent){Q q=getItem(n);LinearLayout row=new LinearLayout(a);row.setOrientation(LinearLayout.VERTICAL);row.addView(text(a,q.club,15f,true));row.addView(text(a,league(q.code)+"  •  league position #"+q.rank+"  •  "+q.points+" pts",11.8f,false));return row;}};}
 public static void show(Activity a){NativeWorldCenter.load(a);final boolean pause=NativePause.begin();LinearLayout root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);TextView note=text(a,"UCL and Europa League renew each season. Top-five places use league tables; external places are estimated. Three Europa places per league include the current league fallback for cup places.",13f,false);note.setBackgroundColor(0xfff2f2f2);root.addView(note);Button groups=new Button(a);groups.setText("CHAMPIONS LEAGUE • CURRENT SEASON / HISTORY");groups.setOnClickListener(v->NativeChampionsLeague.show(a));root.addView(groups);Button europaResults=new Button(a);europaResults.setText("EUROPA LEAGUE • CURRENT SEASON / HISTORY");europaResults.setOnClickListener(v->NativeChampionsLeague.showEuropa(a));root.addView(europaResults);Button quotas=new Button(a);quotas.setText("QUOTAS • UCL / EUROPA LEAGUE");quotas.setOnClickListener(v->new AlertDialog.Builder(a).setTitle("European places").setMessage(EuropeanPlaces.quotas()).setPositiveButton("Close",null).show());root.addView(quotas);Button registry=new Button(a);registry.setText("EUROPEAN CLUB REGISTRY • 129 CLUBS");registry.setOnClickListener(v->NativeEuropeanRegistry.show(a));root.addView(registry);LinearLayout tabs=new LinearLayout(a);Button champions=new Button(a),europa=new Button(a);champions.setText("CHAMPIONS LEAGUE");europa.setText("EUROPA LEAGUE");tabs.addView(champions,new LinearLayout.LayoutParams(0,-2,1));tabs.addView(europa,new LinearLayout.LayoutParams(0,-2,1));root.addView(tabs);TextView status=text(a,"",12.5f,true);root.addView(status);ListView list=new ListView(a);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));final boolean[] clMode={true};Runnable refresh=()->{ArrayList<Q> rows=qualifiers(clMode[0]);list.setAdapter(adapter(a,rows));status.setText((NativeTransferCalendar.played()>=NativeTransferCalendar.total()?"QUALIFIED FOR NEXT SEASON":"CURRENTLY QUALIFYING")+"  •  "+rows.size()+" TOP-5 SLOTS");champions.setEnabled(!clMode[0]);europa.setEnabled(clMode[0]);};champions.setOnClickListener(v->{clMode[0]=true;refresh.run();});europa.setOnClickListener(v->{clMode[0]=false;refresh.run();});refresh.run();AlertDialog d=new AlertDialog.Builder(a).setTitle("European Qualification").setView(root).setPositiveButton("Close",null).create();d.setOnDismissListener(v->NativePause.end(pause));d.setOnShowListener(v->{Window w=d.getWindow();if(w!=null)w.setLayout(-1,Math.round(a.getResources().getDisplayMetrics().heightPixels*.94f));});d.show();}
}
